/* ============================================================================
 * data/challenges-stego.js - STEGANOGRAPHY (5 challenges)
 * The images are *generated by the app* from deterministic pixel specs
 * (assets/js/artifacts.js + CTF.buildPixels), so nothing external is fetched
 * and the pixel values a learner inspects are provably the embedded ones.
 * ==========================================================================*/
/* global CTF */
(function (root) {
  "use strict";
  var CTF = root.CTF;
  var A = CTF.ARTIFACTS;
  var CAT = "Steganography";

  CTF.register([
    {
      id: "STEGO-001",
      title: "Hidden Pixel",
      category: CAT,
      difficulty: "Easy",
      points: 150,
      objective: "Read a message hidden in the least significant bit of one colour channel.",
      description:
        "The lab renderer below generated a noisy 24x24 image. One colour channel is carrying a message in its least " +
        "significant bit, one bit per pixel, read left to right and top to bottom. Recover it.\n\n" +
        "Red values of row 0 (the first 24 pixels):\n" + A["STEGO-001"].firstRowRed.join(", "),
      skills: ["LSB Steganography", "Binary", "Pixel Inspection"],
      data: {
        artifact: "stego-image",
        spec: A["STEGO-001"].spec,
        channel: "r",
        dumpTitle: "Row 0 - red channel values",
        dump: A["STEGO-001"].firstRowRed.join(", "),
        lsbDump: A["STEGO-001"].lsb,
        meta: "24 x 24, seeded noise, payload in the LSB of the red channel"
      },
      answer: { expects: A["STEGO-001"].flag },
      hints: [
        "LSB means the last bit of each value: 68 -> 0, 143 -> 1. Write those bits down in pixel order.",
        "The row 0 bits read 01000110 01001100 01000001 - group them by eight.",
        "Each group of eight bits is one ASCII character: 01000110 = 'F'. Continue through the following rows."
      ],
      flag: A["STEGO-001"].flag,
      explanation:
        "Least significant bit embedding changes each colour value by at most 1, which is invisible to the eye but " +
        "trivial to extract once you know the channel and the order. Row 0 alone gives you the first three characters, " +
        "and reading bit 0 of each red value across the whole image yields the full message. Detection in the real " +
        "world works the same way: statistical tests look for the unnatural even/odd distribution that embedding " +
        "creates, which is why LSB payloads are considered weak steganography.",
      solutionSteps: [
        "Take the LSB (value AND 1) of the red channel of each pixel.",
        "Read them row by row, left to right.",
        "Group into 8 bit bytes and map through ASCII.",
        "The message is the flag."
      ]
    },
    {
      id: "STEGO-002",
      title: "Last Bit",
      category: CAT,
      difficulty: "Medium",
      points: 250,
      objective: "Extract an LSB payload from a specified channel and region, and express the raw bits correctly.",
      description:
        "A 32x32 lab image hides a message in the LSB of the BLUE channel, row-major from the top left. Before you " +
        "submit the message, the intake form asks for the raw bit pattern of the first eight pixels.\n\n" +
        "Blue values of the first 8 pixels: " + A["STEGO-002"].first8Blue.join(", ") + "\n\n" +
        "Submit the eight LSBs separated by single spaces (for example: 0 1 1 0 0 1 0 1), or submit the full message.",
      skills: ["LSB Steganography", "Bit Extraction", "Channel Selection"],
      data: {
        artifact: "stego-image",
        spec: A["STEGO-002"].spec,
        channel: "b",
        dumpTitle: "First 8 pixels - blue channel values",
        dump: A["STEGO-002"].first8Blue.join(", "),
        meta: "32 x 32, payload in the LSB of the blue channel"
      },
      answer: { expects: [A["STEGO-002"].answer, A["STEGO-002"].flag] },
      hints: [
        "Take each blue value modulo 2: that is the LSB. Write the eight results in pixel order.",
        "The first value is 226, which is even, so the first bit is 0. The second is 99, odd, so 1.",
        "The full eight bit answer is '" + A["STEGO-002"].answer + "'. Continuing across the image decodes to the flag."
      ],
      flag: A["STEGO-002"].flag,
      explanation:
        "This lab drills the mechanical part that people get wrong under pressure: parity. Even value -> bit 0, odd " +
        "value -> bit 1, and the order is row-major unless stated otherwise. Getting the first eight bits right " +
        "proves the extraction model before you commit to decoding a long payload. In real analysis the same habit " +
        "applies - validate the small, checkable piece of a transformation before trusting a large output.",
      solutionSteps: [
        "Read the blue channel of pixels (0,0) to (7,0).",
        "Reduce each value mod 2 to get its LSB.",
        "Write the eight bits in order, space separated.",
        "Optionally continue across the image to decode the whole message."
      ]
    },
    {
      id: "STEGO-003",
      title: "Noisy Picture",
      category: CAT,
      difficulty: "Medium",
      points: 300,
      objective: "Find anomalous pixels by testing them against the expected background value range.",
      description:
        "This 40x24 image looks like uniform grey noise. It is not: every genuine background pixel has all three " +
        "channel values between 90 and 110 inclusive. A handful of pixels break that rule and they were placed " +
        "deliberately.\n\n" +
        "How many pixels fall outside the expected background range?",
      skills: ["Anomaly Detection", "Pixel Statistics", "Range Filtering"],
      data: {
        artifact: "stego-image",
        spec: A["STEGO-003"].spec,
        dumpTitle: "Anomalous pixel coordinates (revealed after solving)",
        dump: A["STEGO-003"].coords.join("  "),
        meta: "40 x 24, background channels constrained to [90, 110]"
      },
      answer: { expects: [A["STEGO-003"].answer, A["STEGO-003"].flag] },
      hints: [
        "Do not look at the picture - look at the numbers. Filter pixels where any channel is below 90 or above 110.",
        "The planted pixels are pure magenta (255, 0, 255), so they are obvious once you test the range.",
        "There are exactly 7 of them, at coordinates " + A["STEGO-003"].coords.join(", ") + "."
      ],
      flag: A["STEGO-003"].flag,
      explanation:
        "Statistical anomaly beats visual inspection every time. The background was generated inside a narrow band " +
        "[90,110], so any pixel outside that band is synthetic. Counting them gives seven, and their coordinates trace " +
        "a scatter pattern rather than a message - which is the actual lesson: not every anomaly carries a payload, " +
        "some are markers, beacons or artefacts of the tool. Characterising the anomaly (how many, where, what values) " +
        "before concluding what it means is standard forensic discipline.",
      solutionSteps: [
        "Iterate every pixel and test all three channels against [90, 110].",
        "Collect the pixels that fail the test.",
        "Count them: seven.",
        "Record their coordinates as evidence of placement, not of chance."
      ]
    },
    {
      id: "STEGO-004",
      title: "Double Layer",
      category: CAT,
      difficulty: "Hard",
      points: 450,
      objective: "Chain two independent hiding places - an alpha channel pointer and a colour channel payload.",
      description:
        "This 32x16 image is delivered as RGBA. The RGB channels look like ordinary seeded noise and the alpha channel " +
        "looks completely opaque - every value is either 254 or 255. That near-constant alpha is the first layer.\n\n" +
        "Alpha values of row 0: " + A["STEGO-004"].alphaRow0.join(", ") + "\n\n" +
        "Find the pointer, then follow it to the real payload.",
      skills: ["LSB Steganography", "Alpha Channel", "Multi Layer Analysis", "Pointer Following"],
      data: {
        artifact: "stego-image",
        spec: A["STEGO-004"].spec,
        alpha: true,
        channel: "r",
        dumpTitle: "Row 0 - alpha values (layer 1)",
        dump: A["STEGO-004"].alphaRow0.join(", "),
        extraDumps: [
          { title: "Row 9 - red values (layer 2 start)", text: A["STEGO-004"].row9Red.join(", ") }
        ],
        meta: "32 x 16 RGBA, layer 1 = alpha LSB rows 0-2, layer 2 = red LSB rows 9-15"
      },
      answer: { expects: A["STEGO-004"].flag },
      hints: [
        "An alpha channel that only ever takes two adjacent values is a bit channel in disguise. Take the LSB of the row 0 alpha values.",
        "Those bits decode to the text '" + A["STEGO-004"].clue + "' - read it as an instruction, not as the answer.",
        "The pointer names rows 9 to 15 and the red channel: extract the red LSB from row 9 onwards, row-major."
      ],
      flag: A["STEGO-004"].flag,
      explanation:
        "Two layers, two different hiding places, and the first layer exists only to describe the second. The tell is " +
        "the alpha histogram: a genuine opaque image stores 255 everywhere, so a mix of 254 and 255 means someone is " +
        "using the low bit as storage. Decoding those LSBs gives the pointer ROWS9TO15RED, which redirects you to the " +
        "red channel of rows 9 through 15 where the payload sits. This is the shape of real layered obfuscation: a " +
        "small, boring artefact tells you where the interesting data is, and skipping the boring artefact costs you " +
        "hours of blind extraction.",
      solutionSteps: [
        "Histogram the alpha channel: only 254 and 255 appear -> LSB storage.",
        "Extract alpha LSBs from row 0 (continuing into rows 1-2) -> 'ROWS9TO15RED'.",
        "Extract red LSBs from row 9 to row 15, row-major.",
        "Decode the bytes to read the flag."
      ]
    },
    {
      id: "STEGO-005",
      title: "Archive Picture",
      category: CAT,
      difficulty: "Hard",
      points: 500,
      objective: "Combine file signature analysis, strings extraction and two encoding layers on one blob.",
      description:
        "You recovered a " + A["STEGO-005"].size + " byte blob from a lab upload endpoint. It starts like a perfectly " +
        "normal image and it is " + A["STEGO-005"].pngSize + " bytes shorter than the file on disk, which means data " +
        "was appended after the end of the image.\n\n" +
        "Printable strings found in the blob (last two entries are the interesting ones):\n" +
        "  ...\n  " + A["STEGO-005"].strings.slice(-2).join("\n  ") + "\n\n" +
        "Work the tail and recover the flag.",
      skills: ["File Signatures", "strings", "Hexadecimal", "Base64", "Appended Data"],
      data: {
        artifact: "blob",
        hex: A["STEGO-005"].bytesHex,
        strings: A["STEGO-005"].strings,
        signature: A["STEGO-005"].signature,
        signatureScan: A["STEGO-005"].signatureScan,
        dumpBytes: 128,
        meta: "PNG body + 8 null bytes + note + hex(base64(flag))"
      },
      answer: { expects: A["STEGO-005"].flag },
      hints: [
        "Compare the file size with the size of the image data: the difference is appended content after IEND.",
        "Run a strings pass over the blob. One note tells you the payload is 'encoded twice', and the last run is pure hex.",
        "Hex decode that last run to get base64, then base64 decode to get the flag."
      ],
      flag: A["STEGO-005"].flag,
      explanation:
        "Appending data after a file's logical end is one of the oldest hiding tricks, and it survives because most " +
        "parsers stop at the format's terminator (here the IEND chunk). Three techniques stack up: signature scanning " +
        "to confirm what the container really is, size comparison to prove extra bytes exist, and a strings pass to " +
        "surface anything printable. The note in the tail says 'encoded twice', and indeed the payload is base64 " +
        "wrapped in hex. The habit worth keeping: when a file's declared format and its length disagree, look at what " +
        "comes after the end.",
      solutionSteps: [
        "Verify the leading signature: 89 50 4E 47 0D 0A 1A 0A -> PNG.",
        "Note the total size exceeds the PNG data size -> appended payload.",
        "strings over the blob reveals a note and a long hex run at the tail.",
        "Hex decode -> base64; base64 decode -> the flag."
      ]
    }
  ]);
})(typeof globalThis !== "undefined" ? globalThis : window);
